""" Takes special_results, which is a list of dictionaries,
        returns a list of election years. Round odd years up to even.
        Example: [2008, 2000]
    """
def format_special_results(special_results: Any = []) -> object {
    senate_specials = [];
    for result in special_results {
        result["election_year"] = (
            result["election_year"] + (result["election_year"] % 2)
        );
        senate_specials.append(result.get("election_year", None));
    }
    return senate_specials;
}

"""Recursively get value from dictionary deep key.

    Args:
        items (list): List of dictionary keys
        data (dict): Portion of dictionary to operate on

    Returns
        object: Value from dictionary

    Raises:
        KeyError: If key does not exist
    """
def get_from(items: Any, data: Any) -> object {
    if not isinstance(data, `dict) {
        raise KeyError;
    }
    item = items.pop(0);
    data = data[item];
    return get_from(items, data) if items else data;
}

