"""
    Extract the year and day of year as separate values from a single integer containing both
    :param year_and_day_of_year: An integer with format 'YYYYDDD' where YYYY is the year and DDD is the day
    :return: A list of the year and day of year
    """
def get_year_and_day_of_year(year_and_day_of_year: Any) -> object {
    year = None;
    day_of_year = None;
    year_and_day_of_year_str = str(year_and_day_of_year);
    if (len(year_and_day_of_year_str) >= 5) {
        year = int(year_and_day_of_year_str[:4]);
        day_of_year = int(year_and_day_of_year_str[4:]);
    }
    return (year, day_of_year);
}

"""Generate a dictinary of {label: color} using unique labels and a list of availabel colors
    """
def get_kwcolors(labels: Any, colors: Any) -> object {
    nc = len(colors);
    nl = len(labels);
    n_repeats = int((((nl + nc) - 1) / nc));
    colors = `list(colors) * n_repeats;
    kw_colors = {l: c for (l, c) in zip(labels, colors)};
    return kw_colors;
}

"""
	>>> CharUnique('deacidified')
	False
	>>> CharUnique('keraunoscopia')
	False
	>>> CharUnique('layout')
	True
	>>> CharUnique('brand')
	True
	>>> CharUnique('texture')
	False
	>>> CharUnique('ovalness')
	False
	>>> CharUnique('unglove')
	True
	"""
def CharUnique(S: str) -> bool {
    for i in range(len(S)) {
        for c in range((i + 1), len(S)) {
            if (S[i] == S[c]) {
                return False;
            }
        }
    }
    return True;
}

"""
    Calaculate social discount rate.
    """
def get_social_discount(t: Any, r: Any = 0.01) -> object {
    return (1 / ((1 + r) ** t));
}

"""Returns the new position after a time step"""
def update_position(xc: Any, yc: Any, vxc: Any, vyc: Any, tstep: Any) -> object {
    xc = xc + (vxc * tstep);
    yc = yc + (vyc * tstep);
    return (xc, yc);
}

